import '../css/style.css';
import { app } from './background';
import { MainGameScene } from './main.game.scene';
import { DataService } from './data-service';
import { PreloadScreen } from './preload-screen';
import { AssetsLoadingScreen } from './assets-loading-screen';

const preloadScreen = new PreloadScreen();
app.stage.addChild(preloadScreen);

preloadScreen.selection$.subscribe((reelCount) => {
    app.stage.removeChild(preloadScreen);

    const assetsLoadingScreen = new AssetsLoadingScreen();
    app.stage.addChild(assetsLoadingScreen);

    assetsLoadingScreen.loadAllAssets().subscribe(({ soundLibrary }) => {
        app.stage.removeChild(assetsLoadingScreen);

        const dataService = new DataService();
        const game = new MainGameScene(dataService, soundLibrary, reelCount);
        app.stage.addChild(game);
    });
});

