import { Container, Graphics, Text } from 'pixi.js';
import { Loader } from '@pixi/loaders';
import { Howl } from 'howler';
import { Observable } from 'rxjs';

export class AssetsLoadingScreen extends Container {
    private progressBar: Graphics;
    private progressText: Text;

    constructor() {
        super();

        this.progressBar = new Graphics();
        this.progressText = new Text('0%', {
            fill: '#ffffff',
            fontSize: 24,
        });
        this.progressText.anchor.set(0.5);

        this.addChild(this.progressBar);
        this.addChild(this.progressText);

        this.progressText.position.set(window.innerWidth / 2, window.innerHeight / 2 - 40);
    }

    loadAllAssets(): Observable<{ soundLibrary: any }> {
        return new Observable((subscriber) => {
            const loader = Loader.shared;

            loader
                .add('slot-machine', 'assets/images/slot-machine.png')
                .add('slot-machine2', 'assets/images/slot-machine-2.png')
                .add('goblin', 'assets/spine/goblins.json')
                .add('mute', 'assets/images/mute.png')
                .add('unmute', 'assets/images/sound-on.png')
                .add('background', 'assets/images/background.png')

            loader.onProgress.add((loader) => {
                this.updateProgress(loader.progress);
            });

            loader.load(() => {
                const soundLibrary: any = {};

                soundLibrary.reelSound = new Howl({ src: ['assets/sounds/spin.mp3'] });
                soundLibrary.winSound = new Howl({ src: ['assets/sounds/win.mp3'] });
                soundLibrary.roarSound = new Howl({ src: ['assets/sounds/roar.mp3'] });
                soundLibrary.loseSound = new Howl({ src: ['assets/sounds/lose.mp3'] });
                soundLibrary.backgroundSound = new Howl({
                    src: ['assets/sounds/background.mp3'],
                    volume: 0.3,
                    loop: true,
                });

                subscriber.next({ soundLibrary });
                subscriber.complete();
            });
        });
    }

    private updateProgress(value: number) {
        const width = 400;
        const height = 20;
        const x = (window.innerWidth - width) / 2;
        const y = window.innerHeight / 2;

        this.progressBar.clear();
        this.progressBar.beginFill(0x00ff00);
        this.progressBar.drawRect(x, y, (value / 100) * width, height);
        this.progressBar.endFill();

        this.progressText.text = `${Math.round(value)}%`;
    }
}