import { Container, Graphics, Text } from 'pixi.js';
import { Subject, Observable } from 'rxjs';

export class PreloadScreen extends Container {
    private selectionSubject = new Subject<number>();

    constructor() {
        super();
        this.createBackground();
        this.createTitleAndOptions();
    }

    private createBackground() {
        const bg = new Graphics();
        bg.beginFill(0x000000);
        bg.drawRect(0, 0, window.innerWidth, window.innerHeight);
        bg.endFill();
        this.addChild(bg);
    }

    private createTitleAndOptions() {
        const wrapper = new Container();
        wrapper.x = window.innerWidth / 2;
        wrapper.y = window.innerHeight / 2;
        this.addChild(wrapper);

        const title = new Text('Choose your slot machine', {
            fill: '#ffffff',
            fontSize: 32,
        });
        title.anchor.set(0.5);
        title.y = -200;
        wrapper.addChild(title);

        const spacing = 280;

        const oneReelBtn = this.createOptionButton('One Reel Machine', 1);
        oneReelBtn.x = -spacing / 2;

        const threeReelsBtn = this.createOptionButton('Three Reels Machine', 3);
        threeReelsBtn.x = spacing / 2;

        wrapper.addChild(oneReelBtn, threeReelsBtn);
    }

    private createOptionButton(label: string, reelCount: number): Container {
        const container = new Container();
        container.interactive = true;
        container.buttonMode = true;

        const preview = this.drawPreviewLayout(reelCount);
        preview.y = -20;
        container.addChild(preview);

        const text = new Text(label, {
            fill: '#ffffff',
            fontSize: 18,
        });
        text.anchor.set(0.5);
        text.y = 100;
        container.addChild(text);

        container.on('pointertap', () => {
            this.selectionSubject.next(reelCount);
            this.selectionSubject.complete();
        });

        return container;
    }

    private drawPreviewLayout(reelCount: number): Container {
        const preview = new Container();

        const cellSize = 30;
        const padding = 5;
        const outer = new Graphics();

        if (reelCount === 1) {
            const totalWidth = 3 * cellSize + 2 * padding;
            const totalHeight = cellSize;

            outer.lineStyle(2, 0xffffff);
            outer.drawRoundedRect(
                -totalWidth / 2 - padding,
                -totalHeight / 2 - padding,
                totalWidth + padding * 2,
                totalHeight + padding * 2,
                10
            );
            preview.addChild(outer);

            for (let i = 0; i < 3; i++) {
                const cell = new Graphics();
                cell.beginFill(0xffffff);
                cell.drawRect(0, 0, cellSize, cellSize);
                cell.endFill();
                cell.x = -totalWidth / 2 + i * (cellSize + padding);
                cell.y = -cellSize / 2;
                preview.addChild(cell);
            }
        } else {
            const cols = 3;
            const rows = 3;
            const totalWidth = cols * cellSize + (cols - 1) * padding;
            const totalHeight = rows * cellSize + (rows - 1) * padding;

            outer.lineStyle(2, 0xffffff);
            outer.drawRoundedRect(
                -totalWidth / 2 - padding,
                -totalHeight / 2 - padding,
                totalWidth + padding * 2,
                totalHeight + padding * 2,
                10
            );
            preview.addChild(outer);

            for (let row = 0; row < rows; row++) {
                for (let col = 0; col < cols; col++) {
                    const cell = new Graphics();
                    cell.beginFill(0xffffff);
                    cell.drawRect(0, 0, cellSize, cellSize);
                    cell.endFill();

                    cell.x = -totalWidth / 2 + col * (cellSize + padding);
                    cell.y = -totalHeight / 2 + row * (cellSize + padding);
                    preview.addChild(cell);
                }
            }
        }

        return preview;
    }

    public get selection$(): Observable<number> {
        return this.selectionSubject.asObservable();
    }
}



