import {Application, Sprite} from 'pixi.js';

const GAME_WIDTH: number = window.innerWidth;
const GAME_HEIGHT: number = window.innerHeight;

export const app: Application = new Application({
    width: GAME_WIDTH,
    height: GAME_HEIGHT,
});

document.body.appendChild(app.view as HTMLCanvasElement);

const background = Sprite.from('assets/images/background.png');
background.width = GAME_WIDTH;
background.height = GAME_HEIGHT;
app.stage.addChild(background);

function resizeBackgroundApp() {
    const canvas = app.view as HTMLCanvasElement;
    const windowWidth = window.innerWidth;
    const windowHeight = window.innerHeight;

    canvas.style.width = `${windowWidth}px`;
    canvas.style.height = `${windowHeight}px`;

    app.renderer.resize(windowWidth, windowHeight);

    background.width = windowWidth;
    background.height = windowHeight;
}

window.addEventListener('resize', resizeBackgroundApp);