import { Container, Text, Graphics, Sprite } from 'pixi.js';
import { gsap } from 'gsap';
import { Bone } from "@pixi-spine/runtime-3.8";
import { Loader } from "@pixi/loaders";
import { Spine} from 'pixi-spine'
import { DataService, FakeSpinResponse } from "./data-service";
import { Howl } from 'howler';

interface Reel {
    container: Container;
    symbols: Text[];
    position: number;
    previousPosition: number;
}

const DEFAULT_SYMBOLS = ['🍒', '💎', '🍋'];

export class MainGameScene extends Container {
    private slotMachineContainer!: Container;
    private spinButtonContainer!: Container;
    private reelsContainer!: Container;
    private reelsMaskContainer!: Container;
    private goblinContainer!: Container;
    private soundButtonContainer!: Container;
    private resultMessageContainer!: Container;
    private slotMachineSprite!: Sprite;
    private soundButtonSprite!: Sprite;
    private reels: Reel[] = [];
    private symbolSize = 100;
    private symbols = DEFAULT_SYMBOLS;
    private reelsMatrix: number[][] = [];
    private isSpinning = false;
    private goblin!: Spine;
    private tickerStarted: boolean = false;
    private highlightedSymbols: Text[] = [];
    private soundLibrary: any = {};
    private lossCounter: number = 0;
    private isMute: boolean = false;
    private reelCount: number;

    constructor(private dataService: DataService, soundLibrary: Record<string, Howl>, reelCount: number) {
        super();

        this.soundLibrary = soundLibrary;
        this.reelCount = reelCount;
        this.soundLibrary.backgroundSound.play();

        this.createSlotMachineContainer();
        this.createGoblin();
        this.loadSlotMachineFrame();
        this.setupResizeHandler();
        this.createReelsMask();
        this.createSpinButton();
        this.createSoundButton()
        this.createReels();
    }

    private createSlotMachineContainer() {
        this.slotMachineContainer = new Container();
        this.addChild(this.slotMachineContainer);
    }

    private loadSlotMachineFrame() {
        const texture = this.reelCount === 3
            ? Loader.shared.resources['slot-machine']?.texture
            : Loader.shared.resources['slot-machine2']?.texture

        if (!texture) {
            return;
        }

        this.slotMachineSprite = new Sprite(texture);
        this.slotMachineSprite.anchor.set(0.5);

        this.slotMachineSprite.x = 30;
        this.slotMachineSprite.y = 0;

        if (this.goblinContainer) {
            this.slotMachineContainer.addChild(this.goblinContainer);
        }

        this.slotMachineContainer.addChild(this.slotMachineSprite);
        this.centerSlotMachine();
    }

    private centerSlotMachine() {
        const centerX = window.innerWidth / 2;
        const centerY = window.innerHeight / 2;
        this.slotMachineContainer.x = centerX;
        this.slotMachineContainer.y = centerY;
    }

    private setupResizeHandler() {
        window.addEventListener('resize', () => this.centerSlotMachine());
    }

    private createReels(matrix?: number[][]) {
        this.resetReelsContainer();

        const reelCount = 3;
        const spacing = 45;
        const symbolSize = this.symbolSize;
        const totalWidth = reelCount * symbolSize + (reelCount - 1) * spacing;
        const startX = -totalWidth / 2;

        for (let i = 0; i < reelCount; i++) {
            const container = new Container();
            container.x = startX + i * (symbolSize + spacing);
            container.y = symbolSize / 2;

            const symbols: Text[] = [];
            for (let j = 0; j < 3; j++) {
                const randomSymbol = this.getRandomSymbol();
                const symbol = this.createSymbol(randomSymbol, j * symbolSize);
                container.addChild(symbol);
                symbols.push(symbol);
            }

            this.reelsContainer.addChild(container);
            this.reels.push({
                container,
                symbols,
                position: 0,
                previousPosition: 0,
            });
        }

        if (matrix) {
            this.createReelsFromMatrix(matrix);
        }

        this.applyReelsMask();
    }

    private resetReelsContainer() {
        if (this.reelsContainer) {
            this.slotMachineContainer.removeChild(this.reelsContainer);
            this.reelsContainer.destroy({ children: true });
        }

        this.reelsContainer = new Container();
        this.reelsContainer.x = 45;
        this.reelsContainer.y = -285;
        this.slotMachineContainer.addChild(this.reelsContainer);

        this.reels = [];
    }

    private createSymbol(text: string, y: number): Text {
        const symbol = new Text(text, {
            fontSize: 80,
            fill: '#ffffff',
        });
        symbol.anchor.set(0.5);
        symbol.x = 0;
        symbol.y = y;
        return symbol;
    }

    private applyReelsMask() {
        if (this.reelsMaskContainer && this.reelsMaskContainer.children.length > 0) {
            const maskGraphics = this.reelsMaskContainer.children[0] as Graphics;
            this.reelsContainer.mask = maskGraphics;
        }
    }

    private createReelsMask() {
        this.reelsMaskContainer = new Container();

        let totalHeight: number;
        this.reelsMaskContainer.x = -6;

        if (this.reelCount === 1) {
            this.reelsMaskContainer.y = -233;
            totalHeight = this.symbolSize * 2 - 7;
        } else {
            this.reelsMaskContainer.y = -285;
            totalHeight = this.symbolSize * 3 + 5;
        }

        this.slotMachineContainer.addChild(this.reelsMaskContainer);

        const mask = new Graphics();
        mask.beginFill(0xff0000, 0.8);
        const reelCount = 3;
        const spacing = 45;

        const totalWidth = reelCount * this.symbolSize + (reelCount - 1) * spacing;
        const offsetX = -totalWidth / 2;

        mask.drawRoundedRect(offsetX, 0, totalWidth, totalHeight, 30);
        mask.endFill();

        this.reelsMaskContainer.addChild(mask);
    }

    private updateReelsInTicker() {
        const maxY = this.symbolSize * this.reels[0]?.symbols.length;

        for (const reel of this.reels) {
            const delta = reel.position - reel.previousPosition;
            reel.previousPosition = reel.position;

            if (Math.abs(delta) < 0.0001) continue;

            for (let i = 0; i < reel.symbols.length; i++) {
                const symbol = reel.symbols[i];
                symbol.y += delta * this.symbolSize;

                if (symbol.y >= maxY) {
                    symbol.y -= maxY;

                    const isFixedFromMatrix = i >= reel.symbols.length - 3;
                    if (!isFixedFromMatrix) {
                        symbol.text = this.getRandomSymbol();
                    }
                }
            }
        }
    }

    private createSpinButton() {
        const width = 240;
        const height = 135;
        const radius = 500;

        this.spinButtonContainer = new Container();
        this.spinButtonContainer.interactive = true;
        (this.spinButtonContainer as any).buttonMode = true;
        this.spinButtonContainer.x = -width / 2;
        this.spinButtonContainer.y = 80;

        const shadow = new Graphics()
            .beginFill(0xaa8800)
            .drawRoundedRect(0, 4, width, height, radius)
            .endFill();
        this.spinButtonContainer.addChild(shadow);

        const base = new Graphics()
            .beginFill(0xffcc00)
            .drawRoundedRect(0, 0, width, height, radius)
            .endFill();
        this.spinButtonContainer.addChild(base);

        const label = new Text('SPIN', {
            fontSize: 28,
            fill: '#000',
            fontWeight: 'bold',
        });
        label.anchor.set(0.5);
        label.x = width / 2;
        label.y = height / 2;
        this.spinButtonContainer.addChild(label);

        this.spinButtonContainer.on('pointerdown', () => {
            this.spinButtonContainer.scale.set(0.96);
            base.tint = 0xffaa00;
        });

        this.spinButtonContainer.on('pointerup', () => {
            this.spinButtonContainer.scale.set(1);
            base.tint = 0xffffff;
            this.startSpin();
        });

        this.spinButtonContainer.on('pointerupoutside', () => {
            this.spinButtonContainer.scale.set(1);
            base.tint = 0xffffff;
        });

        this.slotMachineContainer.addChild(this.spinButtonContainer);
    }

    private startSpin() {
        if (this.isSpinning) return;
        this.isSpinning = true;

        this.dataService.generateFakeSpinResponse().subscribe((response: FakeSpinResponse) => {
            this.reelsMatrix = response.game.result;
            this.createReels(this.reelsMatrix);

            if (!this.tickerStarted) {
                gsap.ticker.add(this.updateReelsInTicker.bind(this));
                this.tickerStarted = true;
            }

            this.animateReels();
        });
    }

    private createReelsFromMatrix(matrix: number[][]) {
        const reelCount = matrix.length;
        const symbolSize = this.symbolSize;
        const spacing = 45;
        const totalWidth = reelCount * symbolSize + (reelCount - 1) * spacing;
        const startX = -totalWidth / 2;

        this.reelsContainer.removeChildren();
        this.reels = [];

        for (let i = 0; i < reelCount; i++) {
            const container = new Container();
            container.x = startX + i * (symbolSize + spacing);
            container.y = -symbolSize / 2;

            const symbols: Text[] = [
                ...this.generateRandomSymbols(27, symbolSize, 4),
                ...this.generateMatrixSymbols(matrix[i], symbolSize, 1),
            ];

            symbols.forEach(symbol => container.addChild(symbol));

            this.reelsContainer.addChild(container);
            this.reels.push({ container, symbols, position: 0, previousPosition: 0 });
        }
    }

    private generateRandomSymbols(count: number, size: number, offsetY: number): Text[] {
        return Array.from({ length: count }, (_, j) => {
            const randIndex = Math.floor(Math.random() * this.symbols.length);
            const symbol = new Text(this.symbols[randIndex], {
                fontSize: 80,
                fill: '#ffffff',
            });
            symbol.anchor.set(0.5);
            symbol.x = 0;
            symbol.y = (offsetY + j) * size;
            return symbol;
        });
    }

    private generateMatrixSymbols(indices: number[], size: number, offsetY: number): Text[] {
        return indices.map((index, j) => {
            const symbol = new Text(this.symbols[index], {
                fontSize: 80,
                fill: '#ffffff',
            });
            symbol.anchor.set(0.5);
            symbol.x = 0;
            symbol.y = (offsetY + j) * size;
            return symbol;
        });
    }

    private animateReels() {
        for (let i = 0; i < this.reels.length; i++) {
            const reel = this.reels[i];
            const target = 30;
            this.soundLibrary.reelSound.play();

            gsap.to(reel, {
                position: target,
                duration: 2 + i * 0.4,
                ease: 'power2.out',
                onComplete: () => {
                    reel.position = target;
                    if (i === this.reels.length - 1) {
                        this.soundLibrary.reelSound.stop();
                        this.isSpinning = false;
                        this.checkWinLine();
                    }
                }
            });
        }
    }

    private getRandomSymbol(): string {
        return this.symbols[Math.floor(Math.random() * this.symbols.length)];
    }

    private createGoblin() {
        const spineData = Loader.shared.resources['goblin']?.spineData;

        if (!spineData) {
            return;
        }

        this.goblin = new Spine(spineData);
        this.goblin.skeleton.setSkinByName('goblin');
        this.goblin.skeleton.setSlotsToSetupPose();
        this.goblin.state.setAnimation(0, 'idle', true);
        this.goblin.scale.set(2);

        this.goblinContainer = new Container();
        this.goblinContainer.addChild(this.goblin);
        this.goblinContainer.x = 0;
        this.goblinContainer.y = 450;
        this.slotMachineContainer.addChildAt(this.goblinContainer, 0);
    }

    private checkWinLine() {
        this.clearHighlights();

        if (this.reelCount === 1) {
            if (this.checkRows(1)) {
                this.playGoblinReaction('win');
                return;
            }
            this.playGoblinReaction('lose');
            return;
        }
        const winCount: Array<boolean> = [];

        for (let row = 0; row < 3; row++) {
            winCount.push(this.checkRows(row));
        }

        const isWin = winCount.some((win) => win);

        if (isWin) {
            this.playGoblinReaction('win');
            return;
        }
        this.playGoblinReaction('lose');
    }

    private checkRows (row: number) {
        const values = this.reelsMatrix.map(col => col[row]);
        const winLine = values.every((val) => val === values[0]);

        if (winLine) {
            const symbolsToHighlight: Text[] = [];

            for (let col = 0; col < 3; col++) {
                const reel = this.reels[col];
                const symbolIndex = (27 + row);
                const symbol = reel.symbols[symbolIndex];

                if (symbol) symbolsToHighlight.push(symbol);
            }
            this.soundLibrary.winSound.play();
            this.highlightSymbols(symbolsToHighlight);
            return true;
        }
        return false;
    }

    private highlightSymbols(symbols: Text[]) {
        for (const symbol of symbols) {
            const glow = new Graphics();

            glow.lineStyle(4, 0x66ccff, 0.8);
            const padding = 5;
            const bounds = symbol.getLocalBounds();

            glow.drawRoundedRect(
                bounds.x - padding,
                bounds.y - padding,
                bounds.width + padding * 2,
                bounds.height + padding * 2,
                20
            );

            glow.endFill();
            glow.zIndex = 2;

            symbol.addChild(glow);

            gsap.to([glow, symbol], {
                alpha: 0.2,
                duration: 0.5,
                repeat: -1,
                yoyo: true,
                ease: 'sine.inOut'
            });

            this.highlightedSymbols.push(symbol);
        }
    }

    private clearHighlights() {
        for (const symbol of this.highlightedSymbols) {
            symbol.removeChildren();
            gsap.killTweensOf(symbol);
        }
        this.highlightedSymbols = [];
    }

    private showResultMessage(type: 'win' | 'lose') {
        if (this.resultMessageContainer) {
            this.slotMachineContainer.removeChild(this.resultMessageContainer);
            this.resultMessageContainer.destroy({ children: true });
        }

        this.resultMessageContainer = new Container();
        this.resultMessageContainer.position.set(0, -390)
        this.slotMachineContainer.addChild(this.resultMessageContainer);

        const messageText = type === 'win' ? 'You win 🎉' : 'Try again 😅';
        const color = type === 'win' ? 0x00ff00 : 0xffff00;

        const text = new Text(messageText, {
            fill: color,
            fontSize: 42,
            fontWeight: 'bold',
            align: 'center',
        });

        text.anchor.set(0.5);
        text.position.set(0, 0);
        this.resultMessageContainer.addChild(text);

        gsap.to(this.resultMessageContainer, {
            alpha: 0,
            duration: 0.5,
            delay: 2.5,
            onComplete: () => {
                this.slotMachineContainer.removeChild(this.resultMessageContainer);
                this.resultMessageContainer.destroy({ children: true });
            }
        });
    }

    private playGoblinReaction(type: 'win' | 'lose') {
        if (!this.goblin) return;

        if (type === 'win') {
            this.performGoblinAttack();
            this.showResultMessage('win');

        } else if (type === 'lose') {
            this.showResultMessage('lose');
            this.lossCounter++;
            if ((this.lossCounter -1) %3 === 0) {
                this.performGoblinLoss();
            }
        }
    }

    private performGoblinAttack() {
        if (!this.goblin || !this.goblinContainer) return;

        const goblin = this.goblin;
        const container = this.goblinContainer;
        const leftArm = goblin.skeleton.findBone('left arm') as Bone;

        const originalX = container.x;

        goblin.state.setAnimation(0, 'walk', true);

        this.soundLibrary.roarSound.play();

        gsap.to(container, {
            x: originalX + 400,
            duration: 0.8,
            ease: 'power1.inOut',
            onComplete: () => {
                goblin.state.setAnimation(0, 'idle', true);

                gsap.to(leftArm, {
                    rotation: 130,
                    duration: 0.5,
                    ease: 'power2.out',
                    onUpdate: () => goblin.skeleton.updateWorldTransform(),
                    onComplete: () => {
                        gsap.to(leftArm, {
                            rotation: 90,
                            duration: 0.2,
                            repeat: 3,
                            yoyo: true,
                            ease: 'power1.inOut',
                            onUpdate: () => goblin.skeleton.updateWorldTransform(),
                            onComplete: () => {
                                gsap.to(leftArm, {
                                    rotation: 45,
                                    duration: 0.4,
                                    ease: 'power2.inOut',
                                    onUpdate: () => goblin.skeleton.updateWorldTransform(),
                                    onComplete: () => {
                                        container.scale.x = -1;
                                        goblin.state.setAnimation(0, 'walk', true);

                                        gsap.to(container, {
                                            x: originalX,
                                            duration: 1,
                                            ease: 'power1.inOut',
                                            onComplete: () => {
                                                this.soundLibrary.roarSound.stop();
                                                this.soundLibrary.winSound.stop();
                                                goblin.state.setAnimation(0, 'idle', true);
                                                container.scale.x = 1;
                                            }
                                        });
                                    }
                                });
                            }
                        });
                    }
                });
            }
        });
    }

    private performGoblinLoss() {
        if (!this.goblin || !this.goblinContainer) return;

        const goblin = this.goblin;
        const container = this.goblinContainer;
        const originalX = container.x;

        container.scale.x = -1;

        goblin.state.setAnimation(0, 'walk', true);
        this.soundLibrary.loseSound.play();

        gsap.to(container, {
            x: originalX - 400,
            duration: 1.2,
            ease: 'power1.inOut',
            onComplete: () => {
                goblin.state.setAnimation(0, 'walk', true);
                container.scale.x = 1;

                gsap.to(container, {
                    x: originalX,
                    duration: 1,
                    ease: 'power1.inOut',
                    onComplete: () => {
                        this.soundLibrary.loseSound.stop();
                        goblin.state.setAnimation(0, 'idle', true);
                    }
                });
            }
        });
    }

    private createSoundButton() {
        this.soundButtonContainer = new Container();
        this.soundButtonContainer.interactive = true;
        this.soundButtonContainer.buttonMode = true;
        this.soundButtonContainer.position.set(-208, 118);

        const border = this.createCircularBorder(50, 4);
        this.soundButtonContainer.addChild(border);

        const texture = Loader.shared.resources[this.isMute ? 'unmute' : 'mute']?.texture;
        if (!texture) return;

        this.soundButtonSprite = new Sprite(texture);
        this.soundButtonSprite.anchor.set(0.5);
        this.soundButtonSprite.width = 50;
        this.soundButtonSprite.height = 50;
        this.soundButtonContainer.addChild(this.soundButtonSprite);

        this.soundButtonContainer.scale.y = 0.8;
        this.soundButtonContainer.skew.x = -0.3;

        this.soundButtonContainer.on('pointerdown', () => this.toggleSound());
        this.slotMachineContainer.addChild(this.soundButtonContainer);
    }

    private toggleSound() {
        this.isMute = !this.isMute;
        Howler.mute(this.isMute);

        const key = this.isMute ? 'unmute' : 'mute';
        const newTexture = Loader.shared.resources[key]?.texture;
        if (newTexture) {
            this.soundButtonSprite.texture = newTexture;
        }
    }

    private createCircularBorder(size: number, borderThickness: number): Graphics {
        const border = new Graphics();
        border.lineStyle(borderThickness, 0x000000);
        border.drawCircle(0, 0, size / 2 + borderThickness / 2);
        return border;
    }
}


