import { Observable } from "rxjs";

export interface FakeSpinResponse {
    game: {
        result: Array<Array<number>>
    }
}

export class DataService {
    constructor() {}

    generateFakeSpinResponse(): Observable<FakeSpinResponse> {
        return new Observable((subscriber) => {
            const numReels = 3;
            const numRows = 3;
            const symbolCount = 3;

            const reels: number[][] = [];

            for (let i = 0; i < numReels; i++) {
                const column: number[] = [];
                for (let j = 0; j < numRows; j++) {
                    column.push(Math.floor(Math.random() * symbolCount));
                }
                reels.push(column);
            }

            const result = {
                game: {
                    result: [...reels]
                }
            };

            subscriber.next(result);
            subscriber.complete();
        });
    }
}
